package main

import (
	"context"
	"flag"
	"os"
	"os/signal"

	"legagent/app/services"
)

// runMigrateRowStamps 為既有資料表補上 created_at / updated_at；可重複執行。
//
//	go run . migrate-row-stamps
//
// @ai:generated by=claude-opus-5-5 date=2026-11-10
// @ai:purpose 一次性的結構遷移，與建表、匯入分開，執行前可先停下會寫入同一批表的匯入
// @ai:input args 子命令參數
// @ai:output none
// @ai:sideeffect 新增欄位、觸發器與索引並回填建立時間、失敗時 os.Exit
func runMigrateRowStamps(args []string) {
	fs := flag.NewFlagSet("migrate-row-stamps", flag.ExitOnError)
	cfgPath := fs.String("config", defaultConfigPath, "config.yaml 路徑")
	_ = fs.Parse(args)

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt)
	defer stop()

	cfg, log := mustLoad(*cfgPath)
	db := mustOpenDB(cfg, log)
	defer db.Close()

	stats, err := services.MigrateRowStamps(ctx, db, log)
	if err != nil {
		db.Close()
		os.Exit(1)
	}
	log.Info("row stamps ready", "tables", stats.Tables, "added", stats.Added,
		"backfilled", stats.Backfilled, "law_tables", stats.LawTables)
}
